package com.quicknotes.app;
import android.content.*;import android.graphics.Color;import org.json.*;import java.util.*;
/** Shared metadata for widget headers and the grouped list picker. */
final class WidgetChoices {
 static class Choice {final String id,title,icon;final int color;final boolean header;Choice(String id,String title,String icon,int color,boolean header){this.id=id;this.title=title;this.icon=icon;this.color=color;this.header=header;}}
 static List<Choice> all(Context c){List<Choice> out=new ArrayList<>();out.add(new Choice(null,"Built-in Lists","",0,true));out.add(new Choice("all","All","all",0xff596579,false));out.add(new Choice("scheduled","Scheduled","calendar",0xffff3b30,false));out.add(new Choice("today","Today","calendar",0xff007aff,false));out.add(new Choice("flagged","Flagged","flag",0xffff9500,false));out.add(new Choice("completed","Completed","check",0xff34c759,false));out.add(new Choice("urgent","Urgent","alarm",0xffff3b30,false));out.add(new Choice(null,"My Lists","",0,true));JSONArray lists=ReminderWidget.read(c).optJSONArray("lists");List<JSONObject> active=new ArrayList<>();if(lists!=null)for(int n=0;n<lists.length();n++){JSONObject l=lists.optJSONObject(n);if(l!=null&&!l.optBoolean("deleted"))active.add(l);}Collections.sort(active,(a,b)->Double.compare(a.optDouble("order"),b.optDouble("order")));for(JSONObject l:active){int color=0xff007aff;try{color=Color.parseColor(l.optString("color","#007aff"));}catch(Exception ignored){}out.add(new Choice(l.optString("id"),l.optString("title"),l.optString("icon","list"),color,false));}return out;}
 static Choice find(Context c,String id){for(Choice x:all(c))if(!x.header&&x.id.equals(id))return x;return new Choice(id,"List unavailable","list",0xff596579,false);}
 static String symbol(String icon){if(icon.startsWith("emoji:"))return icon.substring(6);switch(icon){case "calendar":return "▦";case "flag":return "⚑";case "check":return "✓";case "alarm":case "clock":return "⏰";case "cart":return "🛒";case "home":return "⌂";case "heart":return "♥";case "star":return "★";case "briefcase":return "▣";case "book":return "▤";case "music":return "♫";case "sun":return "☀";case "moon":return "☾";case "gift":return "🎁";case "fitness":return "🏋";case "plane":return "✈";case "coffee":return "☕";case "leaf":return "🌿";case "car":return "🚗";case "wallet":return "▣";case "tools":return "🔧";case "bell":return "♧";case "pet":return "🐾";case "food":return "🍴";case "mail":return "✉";case "camera":return "📷";case "flower":return "✿";case "shield":return "⛨";case "image":return "▧";default:return "☷";}}
}
